"% Steady level-flight trim analysis for transport aircraft
% Clears workspace to ensure clean execution
clear;
clc;

% --- Given Parameters ---
% Weight and Geometry
W = 175000.0;      % lbf
S = 2050.0;        % ft^2

% Flight Conditions
h = 26000.0;       % ft (Altitude)
V = 690.0;         % ft/s (True Airspeed)

% Aerodynamics
CL0 = 0.12;
CLalpha = 4.9;     % /rad
CD0 = 0.023;
k = 0.041;

% Atmosphere
rho0 = 0.0023769;  % slug/ft^3
h_scale = 23800.0; % ft

% --- Calculations ---

% 1. Calculate Air Density
rho = rho0 * exp(-h / h_scale);

% 2. Calculate Dynamic Pressure
qbar = 0.5 * rho * V^2;

% 3. Solve for Angle of Attack (alpha)
%    Condition: Lift = Weight
%    L = qbar * S * CL = W
%    CL = W / (qbar * S)
CL_trim = W / (qbar * S);

%    Lift Model: CL = CL0 + CLalpha * alpha
%    alpha = (CL - CL0) / CLalpha
alpha_rad = (CL_trim - CL0) / CLalpha;
alpha_deg = alpha_rad * (180 / pi);

% 4. Solve for Required Thrust
%    Condition: Thrust = Drag
%    Drag Polar: CD = CD0 + k * CL^2
CD_trim = CD0 + k * (CL_trim^2);

%    Drag = qbar * S * CD
thrust_required = qbar * S * CD_trim;

% --- Output Generation ---
% Create result structure with exact keys
result.alpha_trim_deg = alpha_deg;
result.thrust_lbf = thrust_required;

% Encode to JSON and write to file
jsonStr = jsonencode(result);
fid = fopen('result.json', 'w');
fprintf(fid, '%s', jsonStr);
fclose(fid);"
